// Initialize backfill — pass collections list downstream
const COLLECTIONS = ['Invoice', 'BankStatement', 'BankTransaction', 'Document', 'Email', 'SecuritySettlement', 'Contract', 'Image'];
const LIMIT = 100;
return [{ json: { collections: COLLECTIONS, limit: LIMIT } }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-thumbnailer-backfill", node: "Code: Query Weaviate (no thumbnail)" } });
const axios = require('axios');
const { collections, limit } = $input.first().json;
const WEAVIATE = 'http://weaviate:8080';
const LIMIT = limit || 100;

const allDocs = [];

for (const collection of collections) {
  let cursor = null;
  let pageCount = 0;

  while (true) {
    pageCount++;
    const cursorClause = cursor ? `, after: "${cursor}"` : '';
    const isImage = collection === 'Image';
    const pathField = isImage ? 'file_path' : 'filePath';
    const hashField = isImage ? 'file_hash' : 'fileHash';
    const gql = `{ Get { ${collection}(limit: ${LIMIT}${cursorClause}) { _additional { id } ${pathField} ${hashField} thumbnail_path } } }`;

    let results;
    try {
      const r = await axios.post(`${WEAVIATE}/v1/graphql`, { query: gql }, {
        headers: { 'Content-Type': 'application/json' },
        timeout: 30000
      });
      if (r.data?.errors) {
        logger.warn(`[backfill] GraphQL error for ${collection}: ${JSON.stringify(r.data.errors)}`);
        break;
      }
      results = r.data?.data?.Get?.[collection] || [];
    } catch(e) {
      logger.warn(`[backfill] Request failed for ${collection}: ${e.message}`);
      break;
    }

    if (results.length === 0) break;

    for (const doc of results) {
      if (!doc.thumbnail_path) {
        allDocs.push({
          weaviate_uuid: doc._additional?.id,
          file_path: doc[pathField] || null,
          document_type: collection
        });
      }
    }

    if (results.length < LIMIT) break;
    cursor = results[results.length - 1]?._additional?.id;
    if (!cursor) break;
  }

  const collCount = allDocs.filter(d => d.document_type === collection).length;
  logger.info(`[backfill] ${collection}: found ${collCount} docs without thumbnail`);
}

logger.info(`[backfill] Total docs to process: ${allDocs.length}`);
return allDocs.map(d => ({ json: d }));

// Process ALL items, not just first — required for batch backfill
return $input.all().map(item => {
  const resp = item.json;
  const body = resp.body || resp;
  const thumbPath = body.thumbnail_path || null;
  const uuid = body.weaviate_uuid || null;
  const docType = body.document_type || 'Document';
  if (!thumbPath || !uuid) {
    throw new Error('Missing thumbnail_path or uuid in response: ' + JSON.stringify(body));
  }
  return { json: { thumbnail_path: thumbPath, weaviate_uuid: uuid, document_type: docType } };
});

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-thumbnailer-backfill", node: "Code: Log PATCH Result" } });
// Process ALL items, not just first — required for batch backfill
return $input.all().map(item => {
  const resp = item.json;
  const statusCode = resp.statusCode || 0;
  if (statusCode >= 200 && statusCode < 300) {
    return { json: { result: 'processed' } };
  } else {
    logger.warn(`[backfill] PATCH failed (HTTP ${statusCode})`);
    return { json: { result: 'failed', reason: 'weaviate_patch_failed' } };
  }
});

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-thumbnailer-backfill", node: "Code: Log Generation Error" } });
// The HTTP node runs with onError=continueRegularOutput, so on failure the
// item is the error object and no longer carries weaviate_uuid. Resolve the
// originating request item via pairedItem — only the failed subset reaches
// this branch, so a positional lookup would misalign.
return $input.all().map((item, i) => {
  let src = {};
  try {
    src = $('IF: Has file_path and UUID').itemMatching(i).json;
  } catch (e) {
    logger.warn(`[backfill] Could not resolve source item for index ${i}: ${e.message}`);
  }
  const uuid = src.weaviate_uuid || 'unknown';
  const documentType = src.document_type || 'unknown';
  const filePath = src.file_path || null;
  const status = item.json?.error?.status || item.json?.statusCode || 0;
  const detail = item.json?.error?.message || '';
  const reason = status === 422 ? 'validation_error' : 'generation_failed';
  logger.warn(`[backfill] Generation failed: uuid=${uuid} type=${documentType} status=${status} reason=${reason} path=${filePath} detail=${detail}`);
  return { json: { result: 'failed', uuid, document_type: documentType, status, reason } };
});

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-thumbnailer-backfill", node: "Code: Log Skip (no file_path)" } });
return $input.all().map(item => {
  const uuid = item.json.weaviate_uuid || 'unknown';
  logger.warn(`[backfill] Skipping doc without file_path: ${uuid}`);
  return { json: { result: 'skipped', uuid, reason: 'no_file_path' } };
});

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-thumbnailer-backfill", node: "Code: Summary" } });
const items = $input.all();
let processed = 0, failed = 0, skipped = 0;
const failed_by_reason = {};
for (const item of items) {
  const result = item.json.result;
  if (result === 'processed') processed++;
  else if (result === 'failed') {
    failed++;
    const reason = item.json.reason || 'unknown';
    failed_by_reason[reason] = (failed_by_reason[reason] || 0) + 1;
  }
  else if (result === 'skipped') skipped++;
}
const summary = { processed, failed, skipped_no_path: skipped, total: items.length, failed_by_reason };
logger.info(`[backfill] Summary: ${JSON.stringify(summary)}`);
return [{ json: summary }];
